const item = $input.first().json;
const raw = String(item.data || item.body || '');
const text = raw
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ')
  .trim();
return [{
  json: {
    document_id: item.document_id,
    tenant_id: item.tenant_id,
    title: item.title,
    source_type: item.source_type,
    text,
    page_count: 1,
    used_ocr: false
  }
}];

const fs = require('fs');
const item = $input.first().json;
const { source_type, file_path } = item;

let text = '';
let page_count = 1;
const used_ocr = false;

if (source_type === 'txt') {
  text = fs.readFileSync(file_path, 'utf-8');

} else if (source_type === 'pdf') {
  try {
    // pdf-parse ships with n8n; set NODE_FUNCTION_ALLOW_EXTERNAL=pdf-parse
    const pdfParse = require('pdf-parse');
    const buf = fs.readFileSync(file_path);
    const data = await pdfParse(buf);
    text = data.text || '';
    page_count = data.numpages || 1;
  } catch (_) {
    // empty text -> OCR branch takes over downstream
    text = '';
  }

} else if (source_type === 'docx') {
  try {
    // mammoth ships with many n8n installs; set NODE_FUNCTION_ALLOW_EXTERNAL=mammoth
    const mammoth = require('mammoth');
    const result = await mammoth.extractRawText({ path: file_path });
    text = result.value || '';
  } catch (_) {
    // Fallback: strip XML tags from raw docx bytes (approximate)
    const buf = fs.readFileSync(file_path);
    text = buf.toString('latin1').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  }
}

return [{
  json: {
    document_id: item.document_id,
    tenant_id: item.tenant_id,
    title: item.title,
    file_path: item.file_path,
    source_type,
    text,
    page_count,
    used_ocr
  }
}];

