// Merge OCR text back with original document metadata
const ocrResp = $input.first().json;
const orig = $('IF: Needs OCR').first().json;
const ocrText = ocrResp.choices?.[0]?.message?.content || '';
return [{
  json: {
    document_id: orig.document_id,
    tenant_id: orig.tenant_id,
    title: orig.title,
    file_path: orig.file_path,
    source_type: orig.source_type,
    text: ocrText,
    page_count: orig.page_count || 1,
    used_ocr: true
  }
}];

const item = $input.first().json;
const text = (item.text || '').trim();

if (!text) {
  throw new Error(`No text extracted from document ${item.document_id} (source_type: ${item.source_type})`);
}

const CHUNK_WORDS = 512;
const OVERLAP_WORDS = 50;

const words = text.split(/\s+/).filter(w => w.length > 0);
const chunks = [];
let i = 0;

while (i < words.length) {
  const slice = words.slice(i, i + CHUNK_WORDS);
  const content = slice.join(' ');
  chunks.push({
    content,
    chunk_index: chunks.length,
    page_number: null,
    token_count: Math.ceil(content.length / 4)
  });
  if (i + CHUNK_WORDS >= words.length) break;
  i += CHUNK_WORDS - OVERLAP_WORDS;
}

// Edge case: very short text produces zero chunks with above loop
if (chunks.length === 0) {
  chunks.push({
    content: text,
    chunk_index: 0,
    page_number: null,
    token_count: Math.ceil(text.length / 4)
  });
}

return [{
  json: {
    document_id: item.document_id,
    tenant_id: item.tenant_id,
    source_type: item.source_type,
    page_count: item.page_count || 1,
    used_ocr: item.used_ocr || false,
    chunk_count: chunks.length,
    chunks
  }
}];

// Zip Voyage embeddings with chunk metadata, output one item per chunk
const voyageResp = $input.first().json;
const chunkNode = $('Chunk Text (512/50)').first().json;

const embeddings = voyageResp.data || [];
const chunks = chunkNode.chunks || [];

if (embeddings.length !== chunks.length) {
  throw new Error(
    `Embedding count mismatch: got ${embeddings.length} embeddings for ${chunks.length} chunks`
  );
}

return chunks.map((chunk, i) => ({
  json: {
    document_id: chunkNode.document_id,
    tenant_id: chunkNode.tenant_id,
    content: chunk.content,
    embedding: JSON.stringify(embeddings[i].embedding),
    chunk_index: chunk.chunk_index,
    page_number: chunk.page_number,
    token_count: chunk.token_count,
    metadata: JSON.stringify({ used_ocr: chunkNode.used_ocr }),
    _total_chunks: chunks.length
  }
}));

// Build parameterized SQL row for this chunk
const item = $input.first().json;
return [{
  json: {
    ...item,
    _sql: 'INSERT INTO document_chunks (tenant_id, document_id, content, embedding, chunk_index, page_number, token_count, metadata) VALUES ($1::uuid, $2::uuid, $3, $4::vector, $5, $6, $7, $8::jsonb)',
    _params: [
      item.tenant_id,
      item.document_id,
      item.content,
      item.embedding,
      item.chunk_index,
      item.page_number,
      item.token_count,
      item.metadata
    ]
  }
}];

// Normalise error from any upstream failure
const item = $input.first();
const webhookData = $('Webhook /ingest').first().json;
const errMsg = item.json?.error?.message
  || item.json?.message
  || 'Ingestion pipeline error';
return [{
  json: {
    document_id: webhookData.document_id,
    error_message: errMsg
  }
}];
